    /**
     * Helper function to get nodes for current flow
     * @param {string} active_workspace - current flow
     * @returns 
     */
    async function getNodesForCurrentWorkspace(active_workspace) {

        // GET NODES IN CURRENT WORKSPACE
        console.log("getting nodes for ", active_workspace)
        let nodes = []
        nodes = RED.nodes.filterNodes({ z: active_workspace })
        console.log("nodes2", nodes)
        var parentNode = RED.nodes.workspace(active_workspace) || RED.nodes.subflow(active_workspace) || RED.nodes.submodel(active_workspace);
        nodes.unshift(parentNode);
        nodes = RED.nodes.createExportableNodeSet(nodes);
        console.log("final nodes: ", nodes)
        return nodes
    }

    /**
     * Helper function to determine the type of flow to deploy 
     * @param {*} nodes 
     * @returns - label determining if its causal, knowledge, or regular flow
     */
    async function findModelType(nodes) {
        let cm = 0
        let km = 0
        let label = ""
        for await (const node of nodes) {
            if (node.type === "causeeffect") { cm += 1 }
            if (node.type === "entity" || node.type === "relation" || node.type === "attribute" || node.type === "rule") { km += 1 }
        }

        if (cm === km && cm === 0) {
            label = "NA"
        } else {
            label = cm > km ? "CM" : "KM"
        }
        console.log("Setting label to " + label, "total cm: " + cm, "total km " + km)
        return label
    }

