    /**
     * Iterates through typeql schema dict to build final version of typeql schema
     * @returns aggregated typeql string 
     */
    async function buildTypeql() {
        typeql = ""
        let added_define = false
        for (var type in typeql_schema_dict) {
            if (typeql_schema_dict[type] !== "") {
                if (added_define === false && (type === "attribute" || type === "relation" || type === "entity" || type === "rule")) {
                    typeql += 'define\n'
                    added_define = true
                }
                typeql += typeql_headers[type]
                typeql += typeql_schema_dict[type]
                typeql += newline
            }
        }
        return typeql
    }

